import math


# ---------------------------------------------------------------- helpers
def _ema(xs, n):
    a = 2.0 / (n + 1.0)
    out = [None] * len(xs)
    e = None
    for i, x in enumerate(xs):
        e = x if e is None else e + a * (x - e)
        if i >= n - 1:
            out[i] = e
    return out


def _sma(xs, n):
    out = [None] * len(xs)
    s = 0.0
    for i, x in enumerate(xs):
        s += x
        if i >= n:
            s -= xs[i - n]
        if i >= n - 1:
            out[i] = s / n
    return out


def _sdev(xs, n):
    out = [None] * len(xs)
    s = 0.0
    q = 0.0
    for i, x in enumerate(xs):
        s += x
        q += x * x
        if i >= n:
            y = xs[i - n]
            s -= y
            q -= y * y
        if i >= n - 1:
            v = (q - s * s / n) / (n - 1)
            out[i] = v ** 0.5 if v > 0.0 else 0.0
    return out


def _rsi(cl, n):
    out = [None] * len(cl)
    au = ad = 0.0
    for i in range(1, len(cl)):
        d = cl[i] - cl[i - 1]
        u = d if d > 0 else 0.0
        w = -d if d < 0 else 0.0
        if i <= n:
            au += u / n
            ad += w / n
            if i == n:
                out[i] = 100.0 - 100.0 / (1.0 + au / ad) if ad > 0 else 100.0
        else:
            au = (au * (n - 1) + u) / n
            ad = (ad * (n - 1) + w) / n
            out[i] = 100.0 - 100.0 / (1.0 + au / ad) if ad > 0 else 100.0
    return out


def _rmax(xs, n):
    out = [None] * len(xs)
    for i in range(n, len(xs)):
        out[i] = max(xs[i - n:i])
    return out


def _rmin(xs, n):
    out = [None] * len(xs)
    for i in range(n, len(xs)):
        out[i] = min(xs[i - n:i])
    return out


def _rules(ctx):
    """Ten candidate rules as position series in {-1, 0, +1}, bar-causal."""
    b = ctx.bars
    n = len(b)
    cl = [float(x["c"]) for x in b]
    hi = [float(x["h"]) for x in b]
    lo = [float(x["l"]) for x in b]
    e9, e21, e30, e50, e100 = (_ema(cl, 9), _ema(cl, 21), _ema(cl, 30),
                               _ema(cl, 50), _ema(cl, 100))
    s50 = _sma(cl, 50)
    d50 = _sdev(cl, 50)
    s20 = _sma(cl, 20)
    d20 = _sdev(cl, 20)
    rs = _rsi(cl, 14)
    dh = _rmax(hi, 20)
    dl = _rmin(lo, 20)
    K = 10
    pos = [[0] * n for _ in range(K)]
    for t in range(n):
        p = [0] * K
        if t:
            for k in range(K):
                p[k] = pos[k][t - 1]
        if e9[t] is not None and e30[t] is not None:
            p[0] = 1 if e9[t] > e30[t] else -1
        if e21[t] is not None and e100[t] is not None:
            p[1] = 1 if e21[t] > e100[t] else -1
        if s50[t] is not None:
            p[2] = 1 if cl[t] > s50[t] else -1
        if dh[t] is not None:
            if cl[t] > dh[t]:
                p[3] = 1
            elif cl[t] < dl[t]:
                p[3] = -1
        if rs[t] is not None:
            if rs[t] < 30.0:
                p[4] = 1
            elif rs[t] > 70.0:
                p[4] = -1
            elif (p[4] > 0 and rs[t] > 50.0) or (p[4] < 0 and rs[t] < 50.0):
                p[4] = 0
        if t >= 20 and cl[t - 20] > 0.0:
            p[5] = 1 if cl[t] > cl[t - 20] else -1
        if s20[t] is not None and d20[t] is not None and d20[t] > 0.0:
            up = s20[t] + 2.0 * d20[t]
            dn = s20[t] - 2.0 * d20[t]
            if cl[t] < dn:
                p[6] = 1
            elif cl[t] > up:
                p[6] = -1
            elif (p[6] > 0 and cl[t] >= s20[t]) or (p[6] < 0 and cl[t] <= s20[t]):
                p[6] = 0
        if t >= 5:
            p[7] = 1 if cl[t] < cl[t - 5] else -1
        if s50[t] is not None and d50[t] is not None and d50[t] > 0.0:
            if cl[t] > s50[t] + d50[t]:
                p[8] = 1
            elif cl[t] < s50[t] - d50[t]:
                p[8] = -1
        if e50[t] is not None and t >= 10 and e50[t - 10] is not None:
            if cl[t] > e50[t] and e50[t] > e50[t - 10]:
                p[9] = 1
            elif cl[t] < e50[t] and e50[t] < e50[t - 10]:
                p[9] = -1
            else:
                p[9] = 0
        for k in range(K):
            pos[k][t] = p[k]
    # per-bar rule returns: the position held at t, earned over t -> t+1
    f = [[0.0] * n for _ in range(K)]
    for t in range(n - 1):
        if cl[t] > 0.0 and cl[t + 1] > 0.0:
            r = math.log(cl[t + 1] / cl[t])
            for k in range(K):
                f[k][t] = pos[k][t] * r
    return pos, f


def _nw(x, m, q):
    """Newey-West HAC standard deviation of the mean-scaled series."""
    n = len(x)
    g0 = 0.0
    for v in x:
        d = v - m
        g0 += d * d
    g0 /= n
    tot = g0
    for j in range(1, q + 1):
        g = 0.0
        for t in range(j, n):
            g += (x[t] - m) * (x[t - j] - m)
        g /= n
        tot += 2.0 * (1.0 - j / (q + 1.0)) * g
    return tot ** 0.5 if tot > 0.0 else 0.0


def _stepdown(f, a, bnd, p, rng):
    """Romano-Wolf stepdown over the window f[k][a:bnd]. Returns rejected ks."""
    K = len(f)
    n = bnd - a
    if n < 60:
        return []
    q = int(4.0 * ((n / 100.0) ** (2.0 / 9.0)))
    if q < 1:
        q = 1
    if q > 12:
        q = 12
    fb = [0.0] * K
    om = [0.0] * K
    tk = [0.0] * K
    win = []
    for k in range(K):
        w = f[k][a:bnd]
        win.append(w)
        m = sum(w) / n
        fb[k] = m
        om[k] = _nw(w, m, q)
        tk[k] = (n ** 0.5) * m / om[k] if om[k] > 1e-15 else 0.0
    # prefix sums over the doubled window so a wrapped block is O(1)
    pre = []
    for k in range(K):
        w = win[k]
        acc = [0.0] * (2 * n + 1)
        for t in range(2 * n):
            acc[t + 1] = acc[t] + w[t % n]
        pre.append(acc)
    B = max(20, int(p.B))
    L = max(2, int(p.block))
    pgeo = 1.0 / L
    lq = math.log(1.0 - pgeo) if pgeo < 1.0 else -1e9
    stat = []
    for _ in range(B):
        blocks = []
        tot = 0
        while tot < n:
            u = rng()
            ln = 1 + int(math.log(u if u > 1e-12 else 1e-12) / lq)
            if ln > n:
                ln = n
            if tot + ln > n:
                ln = n - tot
            s = int(rng() * n) % n
            blocks.append((s, ln))
            tot += ln
        row = [0.0] * K
        for k in range(K):
            acc = pre[k]
            tsum = 0.0
            for (s, ln) in blocks:
                tsum += acc[s + ln] - acc[s]
            mb = tsum / n
            row[k] = (n ** 0.5) * (mb - fb[k]) / om[k] if om[k] > 1e-15 else 0.0
        stat.append(row)

    alpha = float(p.alpha)
    kf = max(1, int(p.kfwer))
    active = list(range(K))
    rejected = []
    for _ in range(K):
        if not active:
            break
        col = []
        for row in stat:
            vs = sorted((row[k] for k in active), reverse=True)
            col.append(vs[min(kf, len(vs)) - 1])
        col.sort()
        idx = int(math.ceil((1.0 - alpha) * len(col))) - 1
        if idx < 0:
            idx = 0
        if idx >= len(col):
            idx = len(col) - 1
        crit = col[idx]
        newly = [k for k in active if tk[k] > crit]
        if not newly:
            break
        rejected.extend(newly)
        active = [k for k in active if k not in newly]
    return rejected


def family_init(ctx):
    pos, f = _rules(ctx)
    n = len(ctx.bars)
    state = [int(ctx.p.seed) & 0x7FFFFFFF]

    def rng():
        state[0] = (1103515245 * state[0] + 12345) & 0x7FFFFFFF
        return state[0] / 2147483648.0

    win = max(120, int(ctx.p.win))
    rer = max(20, int(ctx.p.rerun))
    vote = float(ctx.p.vote)
    sig = [0] * n
    rej = []
    nxt = win + 1
    K = len(pos)
    for j in range(n):
        if j >= nxt:
            rej = _stepdown(f, j - win, j, ctx.p, rng)
            nxt = j + rer
        if rej:
            s = 0
            for k in rej:
                s += pos[k][j]
            netv = s / float(len(rej))
            if netv >= vote:
                sig[j] = 1
            elif netv <= -vote:
                sig[j] = -1
    ctx.f_sig = sig
    ctx.f_K = K


def signal(ctx, i):
    return ctx.f_sig[i]
